mapper.select:
select count(*) from reward_drop_log
where member_id = #{memberId}
  and topic_id = #{topicId}
  and node_id = #{nodeId}
  and activity_id = #{activityId}
  and scene_key = #{sceneKey}

select id, member_id as memberId, topic_id as topicId, node_id as nodeId,
       activity_id as activityId, scene_key as sceneKey, drop_type as dropType, param_json as paramJson
from reward_drop_log where id = #{id}

select id, member_id as memberId, topic_id as topicId, node_id as nodeId,
       activity_id as activityId, scene_key as sceneKey, drop_type as dropType, param_json as paramJson
from reward_drop_log where member_id = #{memberId} and topic_id = #{topicId}
  and node_id = #{nodeId} and activity_id = #{activityId} and scene_key = #{sceneKey}
